insert into public.roles(name,description) values('student','Student portal access'),('parent','Parent portal access') on conflict(name) do nothing;
alter table public.students add column if not exists user_id uuid references auth.users(id);
create index if not exists students_user_id_idx on public.students(user_id);
create table if not exists public.subscription_plans(id uuid primary key default gen_random_uuid(),name text not null unique,description text,monthly_price numeric(12,2) not null default 0 check(monthly_price>=0),annual_price numeric(12,2) not null default 0 check(annual_price>=0),max_students integer,max_staff integer,features jsonb not null default '{}'::jsonb,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.subscriptions(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,plan_id uuid not null references public.subscription_plans(id),status text not null default 'trial' check(status in('trial','active','past_due','suspended','cancelled')),billing_cycle text not null default 'monthly' check(billing_cycle in('monthly','annual')),starts_at timestamptz not null default now(),trial_ends_at timestamptz,current_period_start timestamptz,current_period_end timestamptz,provider text,provider_customer_id text,provider_subscription_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id));
alter table public.subscription_plans enable row level security;alter table public.subscriptions enable row level security;revoke all on public.subscription_plans from anon;revoke all on public.subscriptions from anon;grant select on public.subscription_plans to authenticated;grant select,insert,update,delete on public.subscriptions to authenticated;
drop policy if exists subscription_plans_read on public.subscription_plans;create policy subscription_plans_read on public.subscription_plans for select to authenticated using(is_active or private.is_platform_admin());
drop policy if exists subscriptions_tenant on public.subscriptions;create policy subscriptions_tenant on public.subscriptions for all to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids())) with check(private.is_platform_admin() or school_id in(select private.user_school_ids()));
insert into public.subscription_plans(name,description,monthly_price,annual_price,max_students,max_staff,features) values('Free','Starter school plan',0,0,100,15,'{"attendance":true,"fees":true,"homework":true,"exams":true,"reports":true}'),('Standard','Growing school plan',1999,19990,500,50,'{"attendance":true,"fees":true,"homework":true,"exams":true,"reports":true,"communication":true,"parent_portal":true}'),('Premium','Full school SaaS plan',4999,49990,2000,200,'{"attendance":true,"fees":true,"homework":true,"exams":true,"reports":true,"communication":true,"parent_portal":true,"student_portal":true,"storage":true}') on conflict(name) do nothing;
create table if not exists public.documents(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,owner_type text not null check(owner_type in('student','parent','staff','admission','school')),owner_id uuid,category text not null default 'other',file_name text not null,storage_path text not null,mime_type text,size_bytes bigint,uploaded_by uuid references auth.users(id),created_at timestamptz not null default now());
create index if not exists documents_school_owner_idx on public.documents(school_id,owner_type,owner_id);alter table public.documents enable row level security;revoke all on public.documents from anon;grant select,insert,update,delete on public.documents to authenticated;drop policy if exists documents_tenant on public.documents;create policy documents_tenant on public.documents for all to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids())) with check(private.is_platform_admin() or school_id in(select private.user_school_ids()));
drop policy if exists parents_self_access on public.parents;create policy parents_self_access on public.parents for select to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids()) or user_id=auth.uid());
drop policy if exists students_parent_or_self_access on public.students;create policy students_parent_or_self_access on public.students for select to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids()) or user_id=auth.uid() or id in(select sp.student_id from public.student_parents sp join public.parents p on p.id=sp.parent_id where p.user_id=auth.uid()));
drop policy if exists student_attendance_parent_or_self on public.student_attendance;create policy student_attendance_parent_or_self on public.student_attendance for select to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids()) or student_id in(select id from public.students where user_id=auth.uid()) or student_id in(select sp.student_id from public.student_parents sp join public.parents p on p.id=sp.parent_id where p.user_id=auth.uid()));
drop policy if exists student_fees_parent_or_self on public.student_fees;create policy student_fees_parent_or_self on public.student_fees for select to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids()) or student_id in(select id from public.students where user_id=auth.uid()) or student_id in(select sp.student_id from public.student_parents sp join public.parents p on p.id=sp.parent_id where p.user_id=auth.uid()));
drop policy if exists payments_parent_or_self on public.payments;create policy payments_parent_or_self on public.payments for select to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids()) or student_id in(select id from public.students where user_id=auth.uid()) or student_id in(select sp.student_id from public.student_parents sp join public.parents p on p.id=sp.parent_id where p.user_id=auth.uid()));
drop policy if exists report_cards_parent_or_self on public.report_cards;create policy report_cards_parent_or_self on public.report_cards for select to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids()) or student_id in(select id from public.students where user_id=auth.uid()) or student_id in(select sp.student_id from public.student_parents sp join public.parents p on p.id=sp.parent_id where p.user_id=auth.uid()));
drop policy if exists exam_marks_parent_or_self on public.exam_marks;create policy exam_marks_parent_or_self on public.exam_marks for select to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids()) or student_id in(select id from public.students where user_id=auth.uid()) or student_id in(select sp.student_id from public.student_parents sp join public.parents p on p.id=sp.parent_id where p.user_id=auth.uid()));
drop policy if exists timetables_parent_or_self on public.timetables;create policy timetables_parent_or_self on public.timetables for select to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids()) or class_id in(select s.class_id from public.students s where s.user_id=auth.uid()) or class_id in(select s.class_id from public.students s join public.student_parents sp on sp.student_id=s.id join public.parents p on p.id=sp.parent_id where p.user_id=auth.uid()));
drop policy if exists notices_portal_read on public.notices;create policy notices_portal_read on public.notices for select to authenticated using(private.is_platform_admin() or school_id in(select private.user_school_ids()) or audience='all' or(audience='parents' and exists(select 1 from public.parents p where p.user_id=auth.uid() and p.school_id=notices.school_id)) or(audience='students' and exists(select 1 from public.students s where s.user_id=auth.uid() and s.school_id=notices.school_id)));
insert into public.subscriptions(school_id,plan_id,status,billing_cycle,starts_at,trial_ends_at,current_period_start,current_period_end) select s.id,p.id,'trial','monthly',now(),now()+interval '14 days',now(),now()+interval '1 month' from public.schools s cross join lateral(select id from public.subscription_plans where name='Free' limit 1)p where not exists(select 1 from public.subscriptions x where x.school_id=s.id);